// The header at the start of every AOT module (source/ctr_aot_module.h): linked into each module with that chapter's
// generated code, never into the main program. The section names and symbols come from aot_module.ld.
#include "aot/vm_aot.h"

#include "ctr_aot_module.h"
#include "aot_hostsyms.h"

extern char __aotm_image_end[], __aotm_code_end[], __aotm_bss_start[], __aotm_bss_end[];

// aot_hostsyms.c (generated by the build) compiled for the module.
extern const uintptr_t aotmHostSymbols[];

__attribute__((section(".aotm.header"), used)) const CtrAotModuleHeader aotModuleHeader = {
    .magic = CTR_AOT_MODULE_MAGIC,
    .version = CTR_AOT_MODULE_VERSION,
    .headerSize = sizeof(CtrAotModuleHeader),
    .base = CTR_AOT_MODULE_BASE,
    .imageEnd = (uint32_t) __aotm_image_end,
    .codeEnd = (uint32_t) __aotm_code_end,
    .bssStart = (uint32_t) __aotm_bss_start,
    .bssEnd = (uint32_t) __aotm_bss_end,
    .table = &aotTable,
    .hostSymbols = aotmHostSymbols,
    .hostSymbolCount = AOT_HOST_SYMBOL_COUNT,
};
